// =============================================================================
// MOCK API MODE — for demoing the frontend without the Spring Boot backend.
//
// This file simulates every endpoint the real backend exposes, using
// localStorage as a fake database. Every function has the SAME name and
// returns the SAME shape ({ data: ... }, or throws { response: { data: { message } } })
// as the real axios-based client, so none of the page components needed to change.
//
// TO SWITCH BACK TO THE REAL BACKEND: replace this file's contents with the
// original implementation in the commented block at the very bottom of this file.
// =============================================================================

const DELAY_MS = 350; // small artificial delay so loading states are visible

const delay = (value) => new Promise((resolve) => setTimeout(() => resolve(value), DELAY_MS));
const fail = (message, status = 400) => {
  const err = new Error(message);
  err.response = { status, data: { message } };
  return Promise.reject(err);
};

// ---------- tiny localStorage "database" ----------
const DB_KEYS = { USERS: "mock_users", RESUMES: "mock_resumes", SEEDED: "mock_seeded" };

function readDb(key) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}
function writeDb(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}
function nextId(list) {
  return list.length ? Math.max(...list.map((x) => x.id)) + 1 : 1;
}
function currentUserEmail() {
  const stored = localStorage.getItem("user");
  return stored ? JSON.parse(stored).email : null;
}
function currentUserFullName() {
  const stored = localStorage.getItem("user");
  return stored ? JSON.parse(stored).fullName : "";
}

// Seed a few templates once, on first load
const TEMPLATES = [
  { id: 1, name: "Classic Professional", industryCategory: "General", colorScheme: "Navy & White", fontFamily: "Georgia", premiumOnly: false, atsFriendly: true },
  { id: 2, name: "Modern Minimalist", industryCategory: "Tech", colorScheme: "Slate & Teal", fontFamily: "Inter", premiumOnly: false, atsFriendly: true },
  { id: 3, name: "Creative Portfolio", industryCategory: "Creative", colorScheme: "Coral & Charcoal", fontFamily: "Poppins", premiumOnly: true, atsFriendly: false },
  { id: 4, name: "Executive Suite", industryCategory: "Finance", colorScheme: "Black & Gold", fontFamily: "Merriweather", premiumOnly: true, atsFriendly: true },
  { id: 5, name: "Healthcare Clean", industryCategory: "Healthcare", colorScheme: "Blue & White", fontFamily: "Roboto", premiumOnly: false, atsFriendly: true },
  { id: 6, name: "Startup Bold", industryCategory: "Tech", colorScheme: "Purple & White", fontFamily: "Montserrat", premiumOnly: true, atsFriendly: true },
];

// Clean up any previously seeded sample candidate resume from localStorage
function cleanupSeedData() {
  const resumes = readDb(DB_KEYS.RESUMES);
  const filtered = resumes.filter((r) => r.ownerEmail !== "sample.candidate@example.com");
  if (filtered.length !== resumes.length) {
    writeDb(DB_KEYS.RESUMES, filtered);
  }
}
cleanupSeedData();

// ---------- auth ----------
function fakeToken(email) {
  return btoa(`mock-token:${email}:${Date.now()}`);
}

export const authApi = {
  register: ({ fullName, email, password, phone, role }) => {
    const users = readDb(DB_KEYS.USERS);
    if (users.some((u) => u.email.toLowerCase() === (email || "").toLowerCase())) {
      return fail("An account with this email already exists.");
    }
    const user = { id: nextId(users), fullName, email, password, phone, role: role || "JOB_SEEKER" };
    users.push(user);
    writeDb(DB_KEYS.USERS, users);
    return delay({ data: { token: fakeToken(email), fullName, email, role: user.role } });
  },

  login: ({ email, password }) => {
    const users = readDb(DB_KEYS.USERS);
    const user = users.find((u) => u.email.toLowerCase() === (email || "").toLowerCase() && u.password === password);
    if (!user) {
      return fail("Invalid email or password.", 401);
    }
    return delay({ data: { token: fakeToken(email), fullName: user.fullName, email: user.email, role: user.role } });
  },
};

// ---------- resumes (job seeker's own resumes) ----------
export const resumeApi = {
  getAll: () => {
    const email = currentUserEmail();
    const resumes = readDb(DB_KEYS.RESUMES).filter((r) => r.ownerEmail === email);
    return delay({ data: resumes.map(toResumeDto) });
  },

  getById: (id) => {
    const resume = readDb(DB_KEYS.RESUMES).find((r) => String(r.id) === String(id));
    if (!resume) return fail("Resume not found.", 404);
    return delay({ data: toResumeDto(resume) });
  },

  create: (dto) => {
    const email = currentUserEmail();
    const resumes = readDb(DB_KEYS.RESUMES);
    const resume = {
      ...dto,
      id: nextId(resumes),
      ownerEmail: email,
      candidateName: dto.candidateName || currentUserFullName(),
      status: "DRAFT",
      version: 1,
      education: (dto.education || []).map((e, i) => ({ ...e, id: i + 1 })),
      experience: (dto.experience || []).map((e, i) => ({ ...e, id: i + 1 })),
    };
    resumes.push(resume);
    writeDb(DB_KEYS.RESUMES, resumes);
    return delay({ data: toResumeDto(resume) });
  },

  update: (id, dto) => {
    const resumes = readDb(DB_KEYS.RESUMES);
    const idx = resumes.findIndex((r) => String(r.id) === String(id));
    if (idx === -1) return fail("Resume not found.", 404);
    const existing = resumes[idx];
    const updated = {
      ...existing,
      ...dto,
      version: (existing.version || 1) + 1,
      education: (dto.education || []).map((e, i) => ({ ...e, id: i + 1 })),
      experience: (dto.experience || []).map((e, i) => ({ ...e, id: i + 1 })),
    };
    resumes[idx] = updated;
    writeDb(DB_KEYS.RESUMES, resumes);
    return delay({ data: toResumeDto(updated) });
  },

  remove: (id) => {
    const resumes = readDb(DB_KEYS.RESUMES).filter((r) => String(r.id) !== String(id));
    writeDb(DB_KEYS.RESUMES, resumes);
    return delay({ data: null });
  },
};

function toResumeDto(resume) {
  return { ...resume };
}

// ---------- templates ----------
export const templateApi = {
  getAll: () => delay({ data: TEMPLATES }),
  getFree: () => delay({ data: TEMPLATES.filter((t) => !t.premiumOnly) }),
};

// ---------- recruiter search ----------

// Build one lowercase blob of every field a recruiter might reasonably search on,
// not just headline/location/skills. This is what previously made visible resumes
// look "missing" from search even though the visibility checkbox was on.
function buildSearchIndex(r) {
  const parts = [
    r.candidateName, r.title, r.headline, r.summary, r.location, r.address,
    ...(r.skills || []),
    ...(r.experience || []).flatMap((e) => [e.jobTitle, e.company, e.description]),
    ...(r.education || []).flatMap((e) => [e.institution, e.degree, e.fieldOfStudy]),
  ];
  return parts.filter(Boolean).join(" ").toLowerCase();
}

function matchesKeyword(resume, keyword) {
  const kw = (keyword || "").trim().toLowerCase();
  if (!kw) return true;
  const haystack = buildSearchIndex(resume);
  // Split into tokens and require every token to appear somewhere in the resume
  // (order/adjacency no longer matters), so e.g. "react chennai" matches a resume
  // whose headline says "React Developer" and whose location is "Chennai".
  const tokens = kw.split(/[\s,]+/).filter(Boolean);
  return tokens.every((t) => haystack.includes(t));
}

export const recruiterApi = {
  search: (keyword) => {
    const results = readDb(DB_KEYS.RESUMES).filter(
      (r) => r.visibleToRecruiters && matchesKeyword(r, keyword)
    );
    return delay({ data: results.map(toResumeDto) });
  },

  getCandidates: () => {
    const results = readDb(DB_KEYS.RESUMES).filter((r) => r.visibleToRecruiters);
    return delay({ data: results.map(toResumeDto) });
  },
};

const mockApi = { authApi, resumeApi, templateApi, recruiterApi };
export default mockApi;

